{"method":"get_file","path":"app.jsx","content":"// app.jsx — Desktop + Mobile app shells. Each owns its own call state but
// shares persona/provider selection across instances (via parent in mount.jsx).
// Exports to window: DesktopApp, MobileApp.

const { useState, useEffect, useRef } = React;

// ── Top bar (clock ticks live so the screen never feels frozen) ─────────────

function TopBar({ compact, callState, accent }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');

  const live = !(callState === 'idle' || callState === 'ended');
  const sessionLabel = live ? 'LIVE' : (callState === 'ended' ? 'ENDED' : 'IDLE');
  const micLabel = live ? 'ON' : 'OFF';

  return (
    <header className="pp-topbar">
      <div className="pp-brand">
        <span className="pp-brand-mark" />
        <span className="pp-brand-name">TSUBAKI</span>
        {!compact && <span className="pp-brand-sub">v0.4.2 · realtime console</span>}
      </div>
      <div className="pp-topbar-status">
        <span>SESSION <b style={{ color: 'var(--ink)' }}>{sessionLabel}</b></span>
        {!compact && <span>NETWORK <b style={{ color: 'var(--ink)' }}>OK</b></span>}
        {!compact && <span>MIC <b style={{ color: 'var(--ink)' }}>{micLabel}</b></span>}
        <span style={{ fontVariantNumeric: 'tabular-nums' }}>{hh}:{mm}:{ss}</span>
      </div>
    </header>);

}

// ── Sidebar ─────────────────────────────────────────────────────────────────

const NAV = [
{ id: 'call', label: 'SESSIONS', key: 'C' },
{ id: 'personas', label: 'PERSONAS', key: 'P' },
{ id: 'providers', label: 'PROVIDERS', key: 'V' },
{ id: 'settings', label: 'SETTINGS', key: 'S' }];


function Sidebar({ nav, setNav, persona, provider, lang, callState }) {
  return (
    <nav className="pp-side">
      <div className="pp-side-eyebrow">— SECTIONS</div>
      {NAV.map((item) =>
      <button
        key={item.id}
        className={`pp-nav-item ${nav === item.id ? 'on' : ''}`}
        onClick={() => setNav(item.id)}>
          <span>{item.label}</span>
          <span className="pp-nav-key">{item.key}</span>
        </button>
      )}
      <div className="pp-side-foot">
        <div><b>{persona.name}</b> · {lang === 'ja' ? '日本語' : 'EN'}<br />active persona</div>
        <div><b>{provider.name}</b> · {provider.model}<br />active transport</div>
        <div>exec <b>{provider.exec ? provider.exec.toUpperCase() : 'REMOTE'}</b></div>
      </div>
    </nav>);

}

// ── Desktop App ─────────────────────────────────────────────────────────────

function DesktopApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('listening'); // start in an interesting state
  // Session voice language. Upstream routes JA by agent id, so this is a
  // session property — not a per-card preview — and the armed persona is
  // derived from it rather than stored pre-resolved.
  const [lang, setLang] = useState('en');
  const [personaId, setPersonaId] = useState(PERSONAS[0].id);
  const persona = resolvePersona(PERSONAS.find((p) => p.id === personaId), lang);
  const setPersona = (p) => setPersonaId(p.id);
  const [provider, setProvider] = useState(PROVIDERS[0]);
  const [tools, setTools] = useState(TOOLS_DEFAULT);
  // Lifted from CallView so the MicSelector in SettingsView shares the same state
  // (matches the codebase's AppShell, which threads session.muted / toggleMute
  // through to both views).
  const [muted, setMuted] = useState(false);
  const [failover, setFailover] = useState(null);
  const failRef = useRef(false);

  // JA guarantee: whenever the armed persona speaks Japanese on a transport with
  // no JA agent (either side changed), reroute to the JA-capable transport
  // without dropping the session — brief CONNECTING dip, then resume.
  useEffect(() => {
    if (!(lang === 'ja' && !provider.ja) || failRef.current) return;
    failRef.current = true;
    const to = JA_PROVIDER();
    const live = !(callState === 'idle' || callState === 'ended');
    setFailover({ from: provider.name, to: to.name, phase: 'switching' });
    if (live) setCallState('connecting');
    setTimeout(() => {
      setProvider(to);
      if (live) setCallState('listening');
      setFailover((f) => f && { ...f, phase: 'done' });
    }, 1600);
    setTimeout(() => {setFailover(null);failRef.current = false;}, 5600);
  }, [lang, provider]);

  // pretend the agent shifts from speaking to listening after 5s on first load
  useEffect(() => {
    if (callState !== 'listening') return;
    const t = setTimeout(() => setCallState('speaking'), 5000);
    return () => clearTimeout(t);
  }, []);

  return (
    <div className={`pp-app ${tweaks.dark ? 'pp-dark' : ''}`} style={{ '--accent': tweaks.accent }}>
      <TopBar callState={callState} accent={tweaks.accent} />
      <div className="pp-shell">
        <Sidebar nav={nav} setNav={setNav}
        persona={persona} provider={provider} lang={lang}
        callState={callState} />
        <main className="pp-main">
          {nav === 'call' &&
          <CallView
            tweaks={tweaks}
            callState={callState}
            setCallState={setCallState}
            persona={persona}
            provider={provider}
            lang={lang}
            setLang={setLang}
            tools={tools}
            setTools={setTools}
            muted={muted}
            setMuted={setMuted}
            failover={failover}
            dark={tweaks.dark} />
          }
          {nav === 'personas' &&
          <PersonasView persona={persona} setPersona={setPersona} provider={provider}
          lang={lang} setLang={setLang}
          dark={tweaks.dark} accent={tweaks.accent} />
          }
          {nav === 'providers' &&
          <ProvidersView provider={provider} setProvider={setProvider}
          accent={tweaks.accent} />
          }
          {nav === 'settings' &&
          <SettingsView accent={tweaks.accent} tools={tools} setTools={setTools}
          muted={muted} setMuted={setMuted} />
          }
        </main>
      </div>
    </div>);

}

// ── Mobile App ──────────────────────────────────────────────────────────────

function MobileApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('speaking');
  // Session voice language — same model as DesktopApp.
  const [lang, setLang] = useState('en');
  const [personaId, setPersonaId] = useState(PERSONAS[0].id);
  const persona = resolvePersona(PERSONAS.find((p) => p.id === personaId), lang);
  const setPersona = (p) => setPersonaId(p.id);
  const [provider, setProvider] = useState(PROVIDERS[0]);
  const [sheetOpen, setSheetOpen] = useState(false);
  const [tools, setTools] = useState(TOOLS_DEFAULT);
  const [toolsOpen, setToolsOpen] = useState(false);
  const [muted, setMuted] = useState(false);
  const [mobileMic, setMobileMic] = useState('iPhone Mic');
  const [failover, setFailover] = useState(null);
  const failRef = useRef(false);

  // Same JA-guarantee reroute as DesktopApp.
  useEffect(() => {
    if (!(lang === 'ja' && !provider.ja) || failRef.current) return;
    failRef.current = true;
    const to = JA_PROVIDER();
    const live = !(callState === 'idle' || callState === 'ended');
    setFailover({ from: provider.name, to: to.name, phase: 'switching' });
    if (live) setCallState('connecting');
    setTimeout(() => {
      setProvider(to);
      if (live) setCallState('listening');
      setFailover((f) => f && { ...f, phase: 'done' });
    }, 1600);
    setTimeout(() => {setFailover(null);failRef.current = false;}, 5600);
  }, [lang, provider]);
  const [caption, setCaption] = useState(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 1].text);
  const [transcriptIdx, setTranscriptIdx] = useState(TRANSCRIPT_SCRIPT.length - 1);

  // Only the cascade STT engine has a manual end-of-turn (half-duplex). Mirrors
  // the codebase's session.canSendTurn (engine === 'cascade').
  const canSendTurn = provider.engine === 'cascade';
  // Mirrors the codebase's session.sendTurnEnabled: the design mock simply
  // tracks LISTENING, while the app keeps SEND armed through dead-air capture
  // (VAD closed, reply not yet committed) so late speech still lands.
  const sendTurnEnabled = canSendTurn && callState === 'listening';

  useEffect(() => {
    if (callState === 'idle' || callState === 'ended') {
      setCaption(callState === 'ended' ? '— call ended —' : 'tap CALL to begin');
      return;
    }
    if (callState === 'connecting') {setCaption('establishing session…');return;}
    if (callState === 'listening') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 2].text);return;}
    if (callState === 'speaking') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 1].text);return;}
    if (callState === 'interrupted') {setCaption('… you interrupted');return;}
  }, [callState]);

  // First-load mock animation: speaking → listening cycle
  useEffect(() => {
    if (callState !== 'speaking') return;
    const t = setTimeout(() => setCallState('listening'), 4200);
    return () => clearTimeout(t);
  }, [callState === 'speaking']);

  const handleCall = () => {
    if (callState === 'idle' || callState === 'ended') {
      setCallState('connecting');
      setTimeout(() => setCallState('listening'), 1200);
      setTimeout(() => setCallState('speaking'), 3000);
    } else {
      setCallState('ended');
    }
  };

  const handleInterrupt = () => {
    if (callState === 'speaking') {
      setCallState('interrupted');
      setTimeout(() => setCallState('listening'), 800);
    }
  };

  // Commit the user's turn (cascade STT): close listening, let the agent reply.
  const handleSendTurn = () => {
    if (sendTurnEnabled) setCallState('speaking');
  };

  const stateLabel = {
    idle: 'IDLE', connecting: 'CONNECTING',
    listening: 'LISTENING', speaking: 'SPEAKING',
    interrupted: 'INTERRUPTED', ended: 'ENDED'
  }[callState];

  const visible = TRANSCRIPT_SCRIPT.slice(0, transcriptIdx + 1);

  return (
    <div className={`pp-app pp-mobile ${tweaks.dark ? 'pp-dark' : ''}`} style={{ '--accent': tweaks.accent }}>
      <TopBar compact callState={callState} accent={tweaks.accent} />

      {/* iOS-ish status row */}
      <div className="pp-mobile-status">
        <span>{persona.name} · {provider.name}</span>
        <span>● LIVE</span>
      </div>

      {nav === 'call' &&
      <>
          <div className="pp-mobile-stage">
            <div className="pp-mobile-stage-top">
              <LangSwitch compact lang={lang} onChange={setLang} />
              {tweaks.providerPreview && <Tag mono>VIA {provider.name}</Tag>}
            </div>
            {failover &&
            <div className={`pp-failover ${failover.phase}`} role="status">
              {failover.phase === 'switching' ?
              <>▲ NO JA AGENT ON {failover.from} — REROUTING → {failover.to}</> :
              <>● REROUTED → {failover.to} · SESSION RESUMED</>}
            </div>
            }

            {/* 50/50 split — orb area on top, caption area on bottom */}
            <div className="pp-mobile-body">
              <div className="pp-orb-area pp-mobile-orb-area">
                <div className="pp-orb-fit pp-mobile-orb-fit">
                  <Orb state={callState} style={tweaks.orbStyle} size="100%" accent={tweaks.accent} dark={tweaks.dark} manual={canSendTurn} />
                </div>
                {(callState === 'listening' || callState === 'interrupted') && <Soundbars count={8} />}
                <div className="pp-mobile-state">
                  <span className={`pp-call-state-dot pp-state-${callState}`} />
                  {stateLabel}
                </div>
                {sendTurnEnabled &&
                <div className="pp-call-manual-hint">MANUAL TURN · PRESS SEND</div>
                }
              </div>

              {tweaks.transcript !== 'off' &&
              <div className="pp-caption-area pp-mobile-caption-area">
                  <ScrollArea className="pp-caption-scroll" dark={tweaks.dark}>
                    <div className="pp-mobile-caption" key={caption}>
                      <span style={{ color: 'var(--accent)' }}>“</span>{caption}<span style={{ color: 'var(--accent)' }}>”</span>
                    </div>
                  </ScrollArea>
                </div>
              }
            </div>
          </div>

          {/* Transcript bottom sheet */}
          {tweaks.transcript === 'drawer' &&
        <div className={`pp-mobile-sheet ${sheetOpen ? 'open' : ''}`}>
              <div className="pp-mobile-sheet-handle" onClick={() => setSheetOpen((o) => !o)}>
                {sheetOpen ? '▾ HIDE TRANSCRIPT' : '▴ TRANSCRIPT · ' + visible.length + ' TURNS'}
              </div>
              <ScrollArea className="pp-mobile-sheet-scroll" dark={tweaks.dark}>
                <div className="pp-mobile-sheet-body">
                  {visible.map((t, i) =>
              <div key={i} className={`pp-turn pp-turn-${t.who}`}>
                      <div className="pp-turn-hd">
                        <span className="pp-turn-who">{t.who === 'user' ? 'YOU' : persona.name}</span>
                        <span className="pp-turn-t">00:{String(i * 7).padStart(2, '0')}</span>
                      </div>
                      <div className="pp-turn-text">{t.text}</div>
                    </div>
              )}
                </div>
              </ScrollArea>
            </div>
        }

          <div className="pp-mobile-controls">
            <Btn small onClick={() => setMuted((m) => !m)} active={muted}
                 aria-label={muted ? 'Unmute microphone' : 'Mute microphone'}><MicGlyph muted={muted} /></Btn>
            <Btn small onClick={handleInterrupt} disabled={callState !== 'speaking'}
          aria-label="Interrupt agent"><InterruptGlyph /></Btn>
            {canSendTurn &&
            <Btn small primed={sendTurnEnabled} onClick={handleSendTurn} disabled={!sendTurnEnabled}
          aria-label="Send turn"><SendGlyph /></Btn>
            }
            <Btn primary onClick={handleCall} danger={!(callState === 'idle' || callState === 'ended')}
          aria-label={callState === 'idle' || callState === 'ended' ? 'Call' : 'Hang up'}>
              {callState === 'idle' || callState === 'ended' ? <WaveGlyph /> : <PhoneHangGlyph />}
            </Btn>
            <ToolsButton tools={tools} open={toolsOpen} setOpen={setToolsOpen} />
          </div>
        </>
      }

      {nav === 'personas' &&
      <div style={{ flex: '1 1 auto', overflow: 'auto' }}>
          <div className="pp-page-hd">
            <div>
              <div className="pp-h-eyebrow">001 / VOICES</div>
              <h1 className="pp-h1">Personas.</h1>
            </div>
            <div className="pp-page-hd-r">
              <LangSwitch compact lang={lang} onChange={setLang} />
            </div>
          </div>
          <div className="pp-grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
            {PERSONAS.map((p, i) => {
            const r = resolvePersona(p, lang);
            const on = persona.id === p.id;
            const ja = lang === 'ja';
            return (
          <div key={p.id}
          className={`pp-persona-card ${on ? 'on' : ''}`}
          onClick={() => setPersona(r)}>
                <div className="pp-persona-top">
                  <div className="pp-persona-num">{String(i + 1).padStart(2, '0')}</div>
                  <div className="pp-persona-top-r">
                    <div
                    className="pp-persona-dot"
                    style={{
                      background: on ? tweaks.accent : `color-mix(in srgb, ${tweaks.accent} 26%, #000)`,
                      boxShadow: on ? `0 0 0 4px color-mix(in srgb, ${tweaks.accent} 22%, transparent)` : 'none'
                    }}
                    role="img"
                    aria-label={on ? 'Active persona' : 'Inactive persona'} />
                  </div>
                </div>
                <div className="pp-persona-name">
                  {ja ? <span className="pp-ja">{r.name}</span> : r.name}
                  {ja && <span className="pp-name-sub">{p.name}</span>}
                </div>
                <div className="pp-persona-accent">{r.accent} · <span className={ja ? 'pp-ja' : ''}>{r.aspect}</span></div>
                <div className="pp-persona-traits">
                  {r.traits.slice(0, 2).map((t) => <span key={t} className={`pp-trait ${ja ? 'pp-ja' : ''}`}>{t}</span>)}
                </div>
                {on && ja && !provider.ja &&
                <div className="pp-ja-warn">▲ {provider.name} — NO JA AGENT · FAILOVER</div>
                }
              </div>);
            })}
          </div>
        </div>
      }

      {nav === 'providers' &&
      <div style={{ flex: '1 1 auto', overflow: 'auto' }}>
          <div className="pp-page-hd">
            <div>
              <div className="pp-h-eyebrow">002 / TRANSPORT</div>
              <h1 className="pp-h1">Providers.</h1>
            </div>
          </div>
          <table className="pp-table">
            <thead>
              <tr>
                <th></th>
                <th>VENDOR</th>
                <th>MODEL</th>
                <th>EXEC</th>
              </tr>
            </thead>
            <tbody>
              {PROVIDERS.map((p) =>
            <tr key={p.id}
            className={provider.id === p.id ? 'on' : ''}
            onClick={() => setProvider(p)}>
                  <td className="pp-table-radio">
                    <span className={provider.id === p.id ? 'on' : ''}
                style={provider.id === p.id ? { background: tweaks.accent, borderColor: tweaks.accent } : null} />
                  </td>
                  <td className="pp-table-vendor">{p.name}{p.ja && <span className="pp-ja-mark" title="Dedicated Japanese agent per persona">JA</span>}</td>
                  <td className="pp-mono-num" style={{ fontSize: 9 }}>{p.model}</td>
                  <td className="pp-mono-num" style={{ fontSize: 9 }}>{(p.exec || 'remote').toUpperCase()}</td>
                </tr>
            )}
            </tbody>
          </table>
        </div>
      }

      {nav === 'settings' &&
      <div style={{ flex: '1 1 auto', overflow: 'auto' }}>
          <div className="pp-page-hd">
            <div>
              <div className="pp-h-eyebrow">003 / CONFIG</div>
              <h1 className="pp-h1">Settings.</h1>
            </div>
          </div>
          <div className="pp-settings-sec">
            <Hr label="AUDIO IN" />
            <FieldRow label="INPUT">
              <MicSelector value={mobileMic} onChange={setMobileMic} muted={muted} onMutedChange={setMuted} />
            </FieldRow>
            <FieldRow label="DENOISE">
              <SwitchRow value={true} onChange={() => {}} />
            </FieldRow>
            <FieldRow label="PUSH-TO-TALK" hint="cascade · send ends turn">
              <SwitchRow value={false} onChange={() => {}} />
            </FieldRow>
          </div>
          <div className="pp-settings-sec">
            <Hr label="BEHAVIOUR" />
            <FieldRow label="LATENCY · 220ms">
              <input type="range" min="80" max="600" defaultValue="220" className="pp-range" style={{ accentColor: tweaks.accent }} />
            </FieldRow>
            <FieldRow label="INTERRUPTIONS" hint="headphones only">
              <SwitchRow value={true} onChange={() => {}} />
            </FieldRow>
          </div>
          <div className="pp-settings-sec">
            <Hr label="TOOLS" />
            {tools.map((t) =>
              <ToolRow key={t.name} name={t.name} label={t.label} on={t.on}
                       onToggle={() => setTools((prev) => prev.map((x) => x.name === t.name ? { ...x, on: !x.on } : x))} />
            )}
          </div>
        </div>
      }

      <nav className="pp-mobile-tabs">
        {NAV.map((item) =>
        <button key={item.id}
        className={`pp-mobile-tab ${nav === item.id ? 'on' : ''}`}
        onClick={() => setNav(item.id)}>
            {item.label}
          </button>
        )}
      </nav>
    </div>);

}

Object.assign(window, { DesktopApp, MobileApp });
