// Tweaks panel for theme/accent/orb-style/transcript/provider preview.

const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
  "dark": false,
  "accent": "#B0122F",
  "orbStyle": "gradient",
  "transcript": "drawer",
  "providerPreview": true
}/*EDITMODE-END*/;

function Root() {
