  return (
    <React.Fragment>
      <DesignCanvas>
        <DCSection
          id="realtime-voice"
          title="Tsubaki"
          subtitle="Realtime voice console — brutalist editorial. Click the orb to start; mid-call you can INTERRUPT and peek the transcript.">
          <DCArtboard id="desktop" label="Desktop · 1440 × 900" width={1440} height={900}>
            <DesktopApp tweaks={t} />
          </DCArtboard>
          <DCArtboard id="mobile" label="Mobile · 390 × 844" width={390} height={844}>
            <MobileApp tweaks={t} />
          </DCArtboard>
