// session.jsx — session routing: which transport + which language the session
// runs on, and what happens when either changes. Shared by DesktopApp and
// MobileApp so the two shells can't drift.
// Exports to window: useSessionRouting, RoutingNotice.
//
// Doctrine (mirrors the app's elevenlabs-agent.ts routing):
// - Language is routing, not configuration. A JA session runs on a dedicated
//   platform agent (tsubaki-<id>-ja); only transports flagged `ja` have one.
// - Failover is a transport concern, and mid-call handover doesn't work
//   upstream. Any change that re-points the session at a different agent
//   (transport or language) ends a live call and opens a NEW session — the old
//   one is never kept alive.
// - The two directions are handled separately, never by one symmetric effect:
//   · JA picked on a transport with no JA agent → the transport moves to the
//     previously chosen JA transport, or the best available one.
//   · A transport with no JA agent picked while JA is armed → the language
//     drops to EN immediately; the user's transport choice wins.

const isLiveState = (s) => !(s === 'idle' || s === 'ended');

// Timings for the mock "end call → connect new session" transition.
const ROUTE_MS = { hangup: 700, listening: 1900, clear: 5600, clearIdle: 4200 };

function useSessionRouting({ callState, setCallState }) {
  const [lang, setLang] = React.useState('en');
  const [provider, setProvider] = React.useState(PROVIDERS[0]);
  const [personaId, setPersonaId] = React.useState(PERSONAS[0].id);
  const [notice, setNotice] = React.useState(null);
  // Last JA-capable transport the user was on — the preferred failover target.
  const lastJaRef = React.useRef(PROVIDERS[0].ja ? PROVIDERS[0].id : null);
  const timersRef = React.useRef([]);
  const callRef = React.useRef(callState);
  callRef.current = callState;

  const clearTimers = () => {
    timersRef.current.forEach(clearTimeout);
    timersRef.current = [];
  };
  const later = (ms, fn) => {timersRef.current.push(setTimeout(fn, ms));};
  React.useEffect(() => clearTimers, []);

  const persona = resolvePersona(PERSONAS.find((p) => p.id === personaId), lang);
  const setPersona = (p) => setPersonaId(p.id);

  const jaTarget = () =>
  PROVIDERS.find((p) => p.id === lastJaRef.current && p.ja) || JA_PROVIDER();

  // Apply a new (transport, language) pair. `kind` names why, for the notice.
  const route = (next, kind) => {
    clearTimers();
    const live = isLiveState(callRef.current);
    const info = {
      kind, live,
      from: provider.name, to: next.provider.name, lang: next.lang,
      agent: next.lang === 'ja' ? jaAgentName({ id: personaId }) : null
    };
    setProvider(next.provider);
    setLang(next.lang);
    if (next.provider.ja) lastJaRef.current = next.provider.id;

    if (!live) {
      // Nothing to tear down. Plain switches need no explanation; the forced
      // ones (failover / downgrade) do.
      if (kind === 'switch') {setNotice(null);return;}
      setNotice({ ...info, phase: 'done' });
      later(ROUTE_MS.clearIdle, () => setNotice(null));
      return;
    }
    // Live: hang up the old session, then open a new one on the new agent.
    setNotice({ ...info, phase: 'switching' });
    setCallState('ended');
    later(ROUTE_MS.hangup, () => setCallState('connecting'));
    later(ROUTE_MS.listening, () => {
      setCallState('listening');
      setNotice((n) => n && { ...n, phase: 'done' });
    });
    later(ROUTE_MS.clear, () => setNotice(null));
  };

  const changeLang = (nextLang) => {
    if (nextLang === lang) return;
    if (nextLang === 'ja' && !provider.ja) {
      const target = jaTarget();
      if (!target) {
        clearTimers();
        setNotice({ kind: 'unavailable', phase: 'done' });
        later(ROUTE_MS.clearIdle, () => setNotice(null));
        return;
      }
      route({ provider: target, lang: 'ja' }, 'failover');
      return;
    }
    // Same transport, different agent (EN ↔ JA on a JA-capable transport).
    route({ provider, lang: nextLang }, 'switch');
  };

  const changeProvider = (nextProvider) => {
    if (nextProvider.id === provider.id) return;
    if (lang === 'ja' && !nextProvider.ja) {
      route({ provider: nextProvider, lang: 'en' }, 'downgrade');
      return;
    }
    route({ provider: nextProvider, lang }, 'switch');
  };

  return { lang, provider, persona, setPersona, changeLang, changeProvider, notice };
}

// Session routing strip. Rendered once per shell, above every page, so a
// downgrade triggered from Providers or Settings is explained where it happens.
function RoutingNotice({ notice }) {
  const t = useT();
  if (!notice) return null;
  const { kind, phase, live, from, to, agent, lang } = notice;
  const text = (() => {
    if (kind === 'unavailable') return t('route.unavailable');
    if (phase === 'switching') return t(`route.${kind}.switching`, { from, to });
    if (kind === 'switch') return t('route.switch.done', { to, lang: t(`lang.name.${lang}`) });
    return t(`route.${kind}.${live ? 'done' : 'idle'}`, { to, agent });
  })();
  return (
    <div className="pp-route-slot">
      <div className={`pp-failover ${phase} pp-route-${kind}`} role="status" aria-live="polite">{text}</div>
    </div>);
}

Object.assign(window, { useSessionRouting, RoutingNotice });

/* ─────────────────────────────────────────────────────────────────────────
   Language layer — EN / 日本語. Loaded after styles.css.
   The app root carries lang + data-lang, so every rule cascades from .pp-app
   instead of per-element .pp-ja opt-ins.
   ───────────────────────────────────────────────────────────────────────── */

/* Per-glyph fallback, always on: Latin stays IBM Plex Mono / Newsreader; kana
   and kanji fall through to Noto. Plex Mono and Newsreader carry no CJK, so
   without this the OS picks (and the 日本語 label in EN mode renders in
   whatever it finds). */
.pp-app { font-family: "IBM Plex Mono", "Noto Sans JP", ui-monospace, monospace; }
.pp-app :is(.pp-h1, .pp-caption, .pp-mobile-caption, .pp-turn-text, .pp-persona-desc, .pp-ja-greet-t) {
  font-family: "Newsreader", "Noto Serif JP", ui-serif, Georgia, serif;
}

/* ── Japanese typography ──────────────────────────────────────────────── */

/* Kinsoku (no 。、」 at line start) and breaking inside long kana runs. */
.pp-app[data-lang="ja"] { line-break: strict; overflow-wrap: anywhere; }

/* Italic Japanese is a synthesized slant — set the serif contexts upright,
   with the extra leading CJK text needs. */
.pp-app[data-lang="ja"] :is(.pp-h1, .pp-caption, .pp-mobile-caption, .pp-turn-text, .pp-persona-desc) {
  font-style: normal;
  font-synthesis: none;
}
.pp-app[data-lang="ja"] .pp-h1 { font-size: 38px; font-weight: 500; letter-spacing: 0.02em; line-height: 1.15; }
.pp-app.pp-mobile[data-lang="ja"] .pp-h1 { font-size: 24px; }
.pp-app[data-lang="ja"] .pp-caption { font-size: 18px; line-height: 1.8; }
.pp-app[data-lang="ja"] .pp-mobile-caption { font-size: 16px; line-height: 1.8; }
.pp-app[data-lang="ja"] .pp-turn-text { font-size: 14px; line-height: 1.8; }
.pp-app[data-lang="ja"] .pp-persona-desc { font-size: 12.5px; line-height: 1.85; }
.pp-app[data-lang="ja"] .pp-lede { line-height: 1.8; }

/* ALL-CAPS tracked labels don't translate: text-transform is a no-op on kana,
   wide tracking fragments words, and 8–9px kanji is illegible. Tighten the
   tracking everywhere and lift the smallest labels to a 10.5px floor. */
.pp-app[data-lang="ja"] :is(
  .pp-side-eyebrow, .pp-spec-l, .pp-field-hd, .pp-turn-hd, .pp-table thead th,
  .pp-mobile-tab, .pp-mobile-sheet-handle, .pp-tools-pop-hd, .pp-tools-pop-foot,
  .pp-switch, .pp-lang-field-l, .pp-lang-btn, .pp-mobile-status, .pp-ja-greet-l,
  .pp-ja-support, .pp-prov-inset-l, .pp-tool-status, .pp-call-manual-hint,
  .pp-ja-mark, .pp-trait
) {
  font-size: 10.5px;
  letter-spacing: 0.04em;
}
.pp-app[data-lang="ja"] :is(
  .pp-h-eyebrow, .pp-nav-item, .pp-tag, .pp-hr-label, .pp-label, .pp-btn,
  .pp-call-state, .pp-call-state-sub, .pp-transcript-hd, .pp-topbar-status,
  .pp-failover, .pp-persona-drop, .pp-mobile-state, .pp-micsel-mute,
  .pp-persona-accent, .pp-brand-sub, .pp-side-foot
) {
  letter-spacing: 0.04em;
}

/* ── Session routing strip ────────────────────────────────────────────── */

/* Zero-height sticky slot: the strip overlays the top of whatever page is
   open (no layout shift) and stays in view while that page scrolls. */
.pp-route-slot {
  position: sticky; top: 0;
  height: 0; overflow: visible;
  z-index: 20;
  flex: 0 0 auto;
}
.pp-route-slot .pp-failover {
  position: absolute; top: 12px; left: 28px; right: 28px;
  margin: 0;
  background: var(--paper);
  box-shadow: 3px 3px 0 var(--line);
}
.pp-mobile .pp-route-slot .pp-failover { top: 8px; left: 14px; right: 14px; margin: 0; }
/* A forced language drop is a warning, not a confirmation — keep it dashed. */
.pp-failover.pp-route-downgrade.done,
.pp-failover.pp-route-unavailable { border-style: dashed; }

