            </div>
            {sendTurnEnabled &&
            <div className="pp-call-manual-hint">{t('call.manualHint')}</div>
            }
          </div>

          {/* Caption half — scrollable text area with macOS-style auto-hiding indicator */}
          {tweaks.transcript !== 'off' &&
          <div className="pp-caption-area">
