// mount.jsx — top-level: design canvas with Desktop + Mobile artboards,
// Tweaks panel for theme/accent/orb-style/transcript/provider preview and the
// Japanese font pairing.

const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
  "dark": false,
  "accent": "#B0122F",
  "orbStyle": "gradient",
  "transcript": "drawer",
  "providerPreview": true,
  "jaSans": "noto",
  "jaSerif": "noto"
}/*EDITMODE-END*/;

function Root() {
  const [t, setTweak] = useTweaks(TWEAK_DEFAULTS);

  return (
    <React.Fragment>
      <DesignCanvas>
        <DCSection
          id="realtime-voice"
          title="Tsubaki"
          subtitle="Realtime voice console — brutalist editorial. Click the orb to start; mid-call you can INTERRUPT and peek the transcript.">
          <DCArtboard id="desktop" label="Desktop · 1440 × 900" width={1440} height={900}>
            <DesktopApp tweaks={t} />
          </DCArtboard>
          <DCArtboard id="mobile" label="Mobile · 390 × 844" width={390} height={844}>
            <MobileApp tweaks={t} />
          </DCArtboard>
        </DCSection>
      </DesignCanvas>

      <TweaksPanel title="Tweaks">
        <TweakSection label="Theme" />
        <TweakToggle label="Dark mode"
          value={t.dark}
          onChange={v => setTweak('dark', v)} />
        <TweakColor label="Accent"
          value={t.accent}
          options={['#B0122F', '#C2410C', '#2563EB', '#16A34A', '#9333EA', '#0A0A09']}
          onChange={v => setTweak('accent', v)} />

        {/* CJK fallbacks only — Latin stays Plex Mono / Newsreader. Switch a
            session to 日本語 to see them. */}
        <TweakSection label="Japanese type" />
        <TweakRadio label="Sans (UI)"
          value={t.jaSans}
          options={JA_FONTS.sans.map(({ value, label }) => ({ value, label }))}
          onChange={v => setTweak('jaSans', v)} />
        <TweakRadio label="Serif (display · captions)"
          value={t.jaSerif}
          options={JA_FONTS.serif.map(({ value, label }) => ({ value, label }))}
          onChange={v => setTweak('jaSerif', v)} />

        <TweakSection label="Orb" />
        <TweakRadio label="Style"
          value={t.orbStyle}
          options={['gradient', 'mono', 'particles']}
          onChange={v => setTweak('orbStyle', v)} />

        <TweakSection label="Transcript" />
        <TweakRadio label="Treatment"
          value={t.transcript}
          options={['caption', 'drawer', 'off']}
          onChange={v => setTweak('transcript', v)} />

        <TweakSection label="Provider" />
        <TweakToggle label="Show provider chip"
          value={t.providerPreview}
          onChange={v => setTweak('providerPreview', v)} />
      </TweaksPanel>
    </React.Fragment>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<Root />);

