/* ─────────────────────────────────────────────────────────────────────────
   Shell layer — Settings grid order and the mobile shell (sections drawer,
   full-parity pages). Loaded after styles.css and i18n.css.
   ───────────────────────────────────────────────────────────────────────── */

/* ── Settings ─────────────────────────────────────────────────────────── */

/* Full-width band above the 2×2 grid, so the grid keeps the app's order:
   AUDIO IN | AUDIO OUT, BEHAVIOUR | TOOLS. */
.pp-settings-sec-wide { grid-column: 1 / -1; border-right: 0; }

/* ── Mobile: menu button + sections drawer ────────────────────────────── */

.pp-menu-btn {
  appearance: none; cursor: pointer;
  display: inline-grid; place-items: center;
  width: 28px; height: 28px; margin-left: -6px;
  background: transparent; color: var(--ink);
  border: 1px solid transparent; border-radius: 0;
  flex: 0 0 auto;
}
.pp-menu-btn:hover { border-color: var(--line); }
.pp-menu-btn[aria-expanded="true"] { background: var(--ink); color: var(--paper); }
.pp-mobile .pp-topbar { gap: 12px; }

/* The layer spans the artboard (.pp-mobile is position: relative). Closed, it
   is visibility-hidden so the drawer's buttons leave the tab order. */
.pp-drawer-layer {
  position: absolute; inset: 0;
  z-index: 40;
  visibility: hidden;
  transition: visibility 0s linear 0.22s;
}
.pp-drawer-layer.open { visibility: visible; transition-delay: 0s; }
.pp-drawer-scrim {
  position: absolute; inset: 0;
  background: color-mix(in srgb, var(--ink) 38%, transparent);
  opacity: 0;
  transition: opacity 0.22s ease;
}
.pp-drawer-layer.open .pp-drawer-scrim { opacity: 1; }
.pp-drawer {
  position: absolute; top: 0; bottom: 0; left: 0;
  width: 240px; max-width: 80%;
  display: flex;
  border-right: 1px solid var(--line);
  box-shadow: 4px 0 0 var(--line);
  transform: translateX(calc(-100% - 6px));
  transition: transform 0.22s cubic-bezier(.2,.7,.3,1);
}
.pp-drawer-layer.open .pp-drawer { transform: none; }
/* The reused desktop Sidebar fills the drawer; it already owns its border. */
.pp-drawer .pp-side { flex: 1 1 auto; border-right: 0; padding-top: 22px; }
@media (prefers-reduced-motion: reduce) {
  .pp-drawer, .pp-drawer-scrim { transition: none; }
}

/* ── Mobile: full-parity pages ────────────────────────────────────────── */

.pp-mobile-page { flex: 1 1 auto; min-height: 0; overflow: auto; }

.pp-mobile .pp-page-hd { flex-wrap: wrap; align-items: flex-start; gap: 12px; }
.pp-mobile .pp-page-hd-r { flex-wrap: wrap; }
.pp-mobile .pp-grid { grid-template-columns: 1fr; }
/* Provider notes don't fit at 390px; the active provider's specs below the
   table carry the detail instead. */
.pp-mobile .pp-th-note, .pp-mobile .pp-table-note { display: none; }
.pp-mobile .pp-prov-detail { padding: 8px 14px 18px; }
.pp-mobile .pp-prov-specs { grid-template-columns: 1fr 1fr; gap: 8px; }
.pp-mobile .pp-settings-sec { border-right: 0; }

