      {LANGS.map((id) => (
        <button
          key={id}
          type="button"
          lang={id}
          className={`tb-lang-btn ${lang === id ? "on" : ""}`}
          aria-pressed={lang === id}
          onClick={(e) => {
            e.stopPropagation();
            onChange(id);
          }}
        >
          {id === "ja" && compact ? "JA" : LANG_LABEL[id]}
        </button>
      ))}
    </span>
  );
}
