                <span className="tb-tools-pop-name">{t.name}</span>
                <span className="tb-tools-pop-label">{t.label}</span>
              </div>
            ))}
          </div>
          <div className="tb-tools-pop-foot">
            <span>↳ CONFIGURE IN SETTINGS</span>
          </div>
        </div>
      )}
    </div>
  );
}
